// END GENERATED GIF FRAMES
namespace {
constexpr int RIDER_S = 5;
constexpr int RIDER_CX = 233;
constexpr int RIDER_X0 = RIDER_CX - RIDER_W * RIDER_S / 2;
constexpr int RIDER_Y0 = 60;
constexpr int GIF_X0 = RIDER_CX - HOME_GIF_W * HOME_GIF_SCALE / 2;
constexpr int GIF_Y0 = 35;

void (*fillRectFn)(int16_t, int16_t, int16_t, int16_t, uint16_t) = nullptr;
void (*printTextFn)(const char *, int, int, int, uint16_t) = nullptr;
void (*drawStatusBarFn)() = nullptr;
}

bool onWaitScreen = false;
bool sliding = false;
int waitSt = 0;
int riderPrevF = -1, riderPrevZ = -2;
bool catForce = false;
int riderAnimMode = 2;

void riderBindRenderer(void (*fillRect)(int16_t, int16_t, int16_t, int16_t, uint16_t),
                       void (*printText)(const char *, int, int, int, uint16_t),
                       void (*drawStatusBar)()) {
  fillRectFn = fillRect;
  printTextFn = printText;
  drawStatusBarFn = drawStatusBar;
}

static uint16_t riderColor(char ch) {
  switch (ch) {
    case 'K': return 0x18C6; case 'H': return 0x2E57; case 'h': return 0xAFBD;
    case 'V': return 0x29ED; case 'v': return 0x7D1C; case 'S': return 0xFEB5;
    case 'E': return 0x18C6; case 'B': return 0xFCB2; case 'R': return 0x9225;
    case 'J': return 0xFC65; case 'j': return 0xD2E2; case 'F': return 0xFF07;
    case 'G': return 0x39E8; case 'P': return 0x3A91; case 'p': return 0x29AC;
    case 'b': return 0x6A25; case 'W': return 0xFFFF; case 'M': return 0xE187;
    case 'm': return 0xA0E5; case 'C': return 0xCE7A; case 'c': return 0x8432;
    case 'T': return 0x2966; case 't': return 0x94B4; case 'L': return 0xFF8F;
    case 'l': return 0x6B6C; case 's': return 0x4185; default: return 0;
  }
}

void drawRider(int f, int zph) {
  if (!fillRectFn || !printTextFn) return;
  fillRectFn(RIDER_X0 - 4, RIDER_Y0 - 40, RIDER_W * RIDER_S + 8, RIDER_H * RIDER_S + 42, 0x0000);
  if (drawStatusBarFn) drawStatusBarFn();
  const int bob = riderAnimMode == 1 ? ((millis() / 180) % 2) * 2 : 0;
  for (int y = 0; y < RIDER_H; y++) {
    const char *row = RIDER[f][y];
    for (int x = 0; row[x] && x < RIDER_W; x++) {
      const uint16_t c = riderColor(row[x]);
      const int px = riderAnimMode == 1 ? RIDER_W - 1 - x : x;
      if (c || row[x] == 'K')
        fillRectFn(RIDER_X0 + px * RIDER_S, RIDER_Y0 + y * RIDER_S - bob,
                   RIDER_S, RIDER_S, c ? c : 0x18C6);
    }
  }
  if (zph >= 0)
    for (int k = 0; k <= zph; k++)
      printTextFn("z", RIDER_CX + 4 + k * 13, RIDER_Y0 + 2 - k * 13,
                  2 + (k > 0 ? 1 : 0), k == zph ? 0x07FF : 0x7BEF);
}

void drawHomeGifFrame(uint8_t frame, bool connected) {
  if (!fillRectFn) return;
  const int yOffset = connected ? 10 : 0;
  const int drawHeight = HOME_GIF_H * HOME_GIF_SCALE - (connected ? 10 : 0);
  fillRectFn(GIF_X0 - 4, GIF_Y0 + yOffset - 4,
             HOME_GIF_W * HOME_GIF_SCALE + 8, drawHeight + 8, 0x0000);
  if (drawStatusBarFn) drawStatusBarFn();
  const uint8_t *pixels = connected ? HOME_CONNECTED_PIXELS[frame] : HOME_DISCONNECTED_PIXELS[frame];
  const int rowsToDraw = connected ? HOME_GIF_H - (10 / HOME_GIF_SCALE) : HOME_GIF_H;
  for (int y = 0; y < rowsToDraw; ++y) {
    int x = 0;
    while (x < HOME_GIF_W) {
      const uint8_t color = pixels[y * HOME_GIF_W + x];
      if (color == 255) { ++x; continue; }
      int end = x + 1;
      while (end < HOME_GIF_W && pixels[y * HOME_GIF_W + end] == color) ++end;
      fillRectFn(GIF_X0 + x * HOME_GIF_SCALE, GIF_Y0 + yOffset + y * HOME_GIF_SCALE,
                 (end - x) * HOME_GIF_SCALE, HOME_GIF_SCALE, HOME_GIF_PALETTE[color]);
      x = end;
    }
  }
}

uint8_t homeGifFrameAt(bool connected, uint32_t elapsedMs) {
  const uint16_t *durations = connected ? HOME_CONNECTED_FRAME_MS : HOME_DISCONNECTED_FRAME_MS;
  const uint8_t frameCount = connected ? HOME_CONNECTED_FRAMES : HOME_DISCONNECTED_FRAMES;
  uint32_t total = 0;
  for (int i = 0; i < frameCount; ++i) total += durations[i];
  uint32_t at = total ? elapsedMs % total : 0;
  for (int i = 0; i < frameCount; ++i) {
    if (at < durations[i]) return (uint8_t)i;
    at -= durations[i];
  }
  return 0;
}

void animateidle() {
  if (!onWaitScreen || sliding) return;
  static unsigned long last = 0;
  const unsigned long now = millis();
  const unsigned long frameCheckMs = riderAnimMode == 2 ? 30 : 100;
  if (!catForce && now - last < frameCheckMs) return;
  const bool force = catForce;
  catForce = false;
  last = now;
  if (riderAnimMode == 2) {
    static bool lastConnected = false;
    static uint32_t animationStartedAt = 0;
    const bool connected = waitSt == 0;
    if (force || connected != lastConnected) {
      lastConnected = connected;
      animationStartedAt = (uint32_t)now;
      riderPrevF = -1;
    }
    const uint8_t frame = homeGifFrameAt(connected, (uint32_t)now - animationStartedAt);
    if (frame == riderPrevF && !force) return;
    riderPrevF = frame;
    riderPrevZ = -1;
    drawHomeGifFrame(frame, connected);
    return;
  }
  int f, zph = -1;
  const int t = (int)((now / (riderAnimMode == 1 ? 260 : 400)) % 2);
  if (waitSt == 1) {
    f = 6;
    zph = (int)((now / 700) % 3);
  } else if (waitSt == 0 && (now % (riderAnimMode == 1 ? 3600 : 5000)) < 1500) {
    f = 4 + (int)((now / (riderAnimMode == 1 ? 180 : 250)) % 2);
  } else if ((now % 3600) < 160) {
    f = 2 + t;
  } else {
    f = t;
  }
  if (f == riderPrevF && zph == riderPrevZ && riderAnimMode == 0) return;
  riderPrevF = f;
  riderPrevZ = zph;
  drawRider(f, zph);
}
